def signal(obs):
    # low turnover mean-reversion on 100-step horizon, held long enough to cover spread
    # only trades when past move is large (>2 sigma) to ensure edge > cost
    # trades cheapest-fee venues only (A,B,C,IDX) to avoid X fees
    try:
        targets = {}
        # keep state for holding periods
        if 'holds' not in obs.state:
            obs.state['holds'] = {a:0 for a in ['A','B','C','IDX','IDX.F','BOND2Y','BOND10Y']}
            obs.state['cnt'] = 0
        holds = obs.state['holds']
        # decrement holds
        for k in list(holds.keys()):
            if holds[k] > 0:
                holds[k] -= 10
        # helper to get past return
        def past_ret(asset, lag):
            try:
                cur = obs.last(asset,'mid')
                hist = obs.hist(asset,'mid', lag+1)
                if hist is None or len(hist) <= lag:
                    return None
                old = hist[0]
                if cur!=cur or old!=old:
                    return None
                return cur - old
            except:
                return None
        # configs: (asset, lag, thresh, std) tuned from visible period
        # std estimates from visible: A_std100~5.0, B~8.5, C~6.3, IDX~6.8, IDXF~7.0, BOND2Y~3.5, BOND10Y~3.8
        cfgs = [
            ('B', 100, 9.0),
            ('IDX.F', 120, 8.0),
            ('C', 100, 7.0),
            ('A', 100, 6.0),
            ('IDX', 100, 7.0),
            ('BOND10Y', 100, 4.0),
            ('BOND2Y', 100, 4.0),
        ]
        for asset, lag, thresh in cfgs:
            if holds.get(asset,0) > 0:
                continue  # keep existing target, avoid churn
            pr = past_ret(asset, lag)
            if pr is None:
                continue
            sig = 0
            # contrarian: past up -> short
            if pr > thresh:
                sig = -1
            elif pr < -thresh:
                sig = 1
            else:
                continue
            # only trade if signal changes substantially vs previous target stored in state
            prev = obs.state.get('pos_'+asset, 0)
            if prev == sig:
                continue
            # set target and hold for lag steps to amortize cost
            targets[asset] = float(sig * 0.85)  # 0.85 leaves room, reduces turnover
            obs.state['pos_'+asset] = sig
            holds[asset] = lag  # hold for lag steps
            # hedge IDX basket? keep separate
        # ensure we return only changed assets; missing = keep previous
        # if no signal, return empty dict (keeps previous)
        return targets
    except:
        return {}

