        if mids[-1] != mids[-1] or mids[-21] != mids[-21]:
            continue
        past20 = mids[-1] - mids[-21]
        # estimate vol of 20-step returns using recent 80 steps
        rets = []
        for i in range(21, len(mids)):
            if mids[i]==mids[i] and mids[i-20]==mids[i-20]:
                rets.append(mids[i]-mids[i-20])
        if len(rets)<20:
            continue
        import math
        # use numpy not allowed but math
        # compute std manually
        mean = sum(rets)/len(rets)
        var = sum((x-mean)**2 for x in rets)/len(rets)
        std = math.sqrt(var) if var>1e-9 else 10.0
        if std<1e-6:
            continue
        z = past20/std
        # threshold 0.5
        if z > 0.7:
            targets[asset]= 1.0
        elif z < -0.7:
            targets[asset]= -1.0
        elif abs(z)<0.3:
            targets[asset]=0.0
        else:
            # keep previous? return nothing to hold
            pass
    # also try B?
    return targets

