    # Try mean reversion on IDX vs basket (diff) - classic arb
    # Compute basket mid
    mA = obs.hist('A','mid',60)
    mB = obs.hist('B','mid',60)
    mC = obs.hist('C','mid',60)
    mIDX = obs.hist('IDX','mid',60)
    if mA is None or mB is None or mC is None or mIDX is None:
        return {}
    if len(mA)<60 or len(mB)<60 or len(mC)<60 or len(mIDX)<60:
        return {}
    # check nans
    for arr in [mA,mB,mC,mIDX]:
        for v in arr[-5:]:
            if v!=v:
                return {}
    diffs=[]
    for i in range(len(mA)):
        if mA[i]==mA[i] and mB[i]==mB[i] and mC[i]==mC[i] and mIDX[i]==mIDX[i]:
            basket = 0.3333*mA[i]+0.6667*mB[i]+0.1667*mC[i]
            diffs.append(mIDX[i]-basket)
        else:
            diffs.append(float('nan'))
    # compute std of diffs
    valid = [x for x in diffs if x==x]
    if len(valid)<30:
        return {}
    mean = sum(valid)/len(valid)
    var = sum((x-mean)*(x-mean) for x in valid)/len(valid)
    std = math.sqrt(var) if var>1e-9 else 10.0
    cur_diff = diffs[-1]
    if cur_diff!=cur_diff:
        return {}
    z = (cur_diff-mean)/std if std>1e-6 else 0
    targets={}
    # if IDX expensive vs basket (z>), short IDX long basket
    # Choose threshold
    thresh=1.0
    # basket weighted: need to set targets proportional? We'll set IDX opposite to A,B,C
    # Simpler: trade IDX vs synthetic? We'll set IDX = -z direction, and A,B,C = +z direction scaled
    if z > thresh:
        # short IDX, long components
        targets['IDX'] = -1.0
        targets['A'] = 0.33
        targets['B'] = 0.66
        targets['C'] = 0.17
    elif z < -thresh:
        targets['IDX'] = 1.0
        targets['A'] = -0.33
        targets['B'] = -0.66
        targets['C'] = -0.17
    elif abs(z)<0.3:
        targets['IDX']=0.0
        targets['A']=0.0
        targets['B']=0.0
        targets['C']=0.0
    return targets

