def safe_corr(x,y):
    xs=[]; ys=[]
    for i in range(len(x)):
        if x[i]==x[i] and y[i]==y[i]:
            xs.append(x[i]); ys.append(y[i])
    if len(xs)<100:
        return float('nan')
    mx=sum(xs)/len(xs); my=sum(ys)/len(ys)
    num=sum((xs[i]-mx)*(ys[i]-my) for i in range(len(xs)))
    denx=sum((xs[i]-mx)**2 for i in range(len(xs)))
    deny=sum((ys[i]-my)**2 for i in range(len(ys)))
    den=math.sqrt(denx*deny)
    return num/den if den>1e-9 else float('nan')
