    prev=st.get('p',0.0)
    # limit change per call to 0.5 for stability
    dp=p-prev
    if dp>0.5: p=prev+0.5
    elif dp<-0.5: p=prev-0.5
    st['p']=p
    return {'IDX':float(p),'IDX.F':float(-p)}

