def signal(obs):
    f = obs.last('IDX.F', 'mid')
    s = obs.last('IDX', 'mid')
    if f is None or s is None:
        return {}
    if f != f or s != s:
        return {}
    if f <= 0 or s <= 0:
        return {}
    b = f - s
    # MA200 via hist
    try:
        hf = obs.hist('IDX.F', 'mid', 210)
        hs = obs.hist('IDX', 'mid', 210)
    except Exception:
        return {}
    n = len(hf) if len(hf) < len(hs) else len(hs)
    if n < 200:
        return {}
    tot = 0.0
    cnt = 0
    for i in range(n - 200, n):
        a = hf[i]
        c = hs[i]
        if a == a and c == c and a > 0 and c > 0:
            tot += (a - c)
            cnt += 1
    if cnt < 100:
        return {}
    ma = tot / cnt
    z = b - ma
    # scale: sd ~27, quantize with deadzone
    # continuous contrarian, clip
    k = 60.0
    t = -z / k
    if t > 1.0:
        t = 1.0
    if t < -1.0:
        t = -1.0
    # deadzone to cut turnover
    if abs(t) < 0.15:
        t = 0.0
    return {'IDX.F': float(t), 'IDX': float(-t)}

