    try:
        ha = obs.hist('A', 'mid', 510)
        hb = obs.hist('B', 'mid', 510)
        hc = obs.hist('C', 'mid', 510)
        hi = obs.hist('IDX', 'mid', 510)
    except Exception:
        return {}
    if ha is None or hb is None or hc is None or hi is None:
        return {}
    try:
        n = len(hi)
    except Exception:
        return {}
    if n < 510:
        return {}
    a0 = ha[-1]; b0 = hb[-1]; c0 = hc[-1]; i0 = hi[-1]
    if not (a0==a0 and b0==b0 and c0==c0 and i0==i0):
        return {}
    # compute diff series for last 500
    # manual loop to avoid nan issues
    s = 0.0
    s2 = 0.0
    cnt = 0
    for k in range(500):
        aa = ha[n-1-k]; bb = hb[n-1-k]; cc = hc[n-1-k]; ii = hi[n-1-k]
        if not (aa==aa and bb==bb and cc==cc and ii==ii):
            continue
        d = ii - (0.3333*aa + 0.6667*bb + 0.1667*cc)
        s += d
        s2 += d*d
        cnt += 1
    if cnt < 400:
        return {}
    mu = s / cnt
    var = s2/cnt - mu*mu
    if not (var==var) or var < 25.0:
        return {}
    sd = var ** 0.5
    if sd < 5.0:
        return {}
    d0 = i0 - (0.3333*a0 + 0.6667*b0 + 0.1667*c0)
    z = (d0 - mu) / sd
    if not (z==z):
        return {}
    # hysteresis with state
    try:
        cur = obs.state.get('pos', 0.0)
    except Exception:
        cur = 0.0
    tgt = cur
    if z > 1.5:
        tgt = -1.0
    elif z < -1.5:
        tgt = 1.0
    elif abs(z) < 0.5:
        tgt = 0.0
    try:
        obs.state['pos'] = tgt
    except Exception:
        pass
    if tgt == 0.0:
        return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
    return {'IDX': tgt, 'A': -tgt*0.3333, 'B': -tgt*0.6667, 'C': -tgt*0.1667}

