# compute spreads for A vs AX, B vs BX, C vs CX
def calc_stats(spread_arr):
    # spread = A_mid - AX_mid
    # compute rolling? simple stats
    n=len(spread_arr)
    # mean, sd
    m=0
    cnt=0
    for x in spread_arr:
        if x==x:
            m+=x
            cnt+=1
    if cnt>0:
        m/=cnt
    var=0
    for x in spread_arr:
        if x==x:
            var+=(x-m)*(x-m)
    sd=(var/cnt)**0.5 if cnt>0 else 0
    # autocorr lag 10
    # compute returns of spread? Actually spread change
    # correlation of spread(t) with next 50 change?
    # we want IC for hedged pair: if spread high, expect to fall -> short spread (long AX short A) return ~ -delta spread
    # approximate forward spread change 50 steps
    forwards=[]
    spreads=[]
    for i in range(n-60):
        if spread_arr[i]==spread_arr[i] and spread_arr[i+50]==spread_arr[i+50]:
            spreads.append(spread_arr[i])
            forwards.append(spread_arr[i+50]-spread_arr[i])
    # correlation
    if len(spreads)>100:
        mx=sum(spreads)/len(spreads)
        my=sum(forwards)/len(forwards)
        num=0
        denx=0
        deny=0
        for a,b in zip(spreads, forwards):
            num+=(a-mx)*(b-my)
            denx+=(a-mx)*(a-mx)
            deny+=(b-my)*(b-my)
        corr=num/((denx*deny)**0.5) if denx>0 and deny>0 else 0
    else:
        corr=0
    return {"mean":m,"sd":sd,"corr_spread_vs_50fut":corr, "n":n}

