import math
# test momentum: past N return vs future 50-step forward return, per asset
def corr(x,y):
    n=len(x)
    mx=sum(x)/n
    my=sum(y)/n
    sxy=sum((a-mx)*(b-my) for a,b in zip(x,y))
    sxx=sum((a-mx)**2 for a in x)
    syy=sum((b-my)**2 for b in y)
    if sxx<=0 or syy<=0:
        return 0.0
    return sxy/((sxx*syy)**0.5)
