    mid_F = obs.last('IDX.F','mid')
    if mid_I is None or mid_F is None or mid_I!=mid_I or mid_F!=mid_F:
        return {}
    prem = mid_F - mid_I
    # time to expiry from meta?
    # obs.meta may have expiry? try to infer via time modulo 1500 if available
    t = obs.t
    mod = t % 1500
    # estimate expected prem decay: hold if prem large relative to time remaining
    # simple threshold that tightens as expiry approaches
    # buckets: early prem high, late prem low
    # target size proportional to prem minus fair based on time?
    # use linear decay expectation: expected prem at expiry 0, so normalized prem = prem / (time_remaining/1500)
    # if time_remaining small, divide magnifies
    time_rem = 1500 - mod
    if time_rem < 50:
        # near expiry flatten to avoid settlement noise
        return {'IDX':0.0,'IDX.F':0.0}
    # normalized prem per year?
    # signal strength
    # threshold 10c
    if prem > 12:
        # short F long IDX hedged, size 1 (15 lots)
        return {'IDX':1.0,'IDX.F':-1.0}
    elif prem < -12:
        return {'IDX':-1.0,'IDX.F':1.0}
    else:
        return {'IDX':0.0,'IDX.F':0.0}

