        st['posA'] = 0
        st['posC'] = 0
        st['posI'] = 0
        st['posF'] = 0
        st['holdA'] = 0
        st['holdC'] = 0
        st['holdH'] = 0

    # decrement holds
    if st['holdA'] > 0:
        st['holdA'] -= 1
    if st['holdC'] > 0:
        st['holdC'] -= 1
    if st['holdH'] > 0:
        st['holdH'] -= 1

    out = {}

