H0=H
def clean(a):
    return np.array([x if np.isfinite(x) else np.nan for x in a], dtype=float)

# Test simple profitability estimates net of spread for imbalance strategy on BOND10Y
# Approximate: we trade at mid but pay half spread per trade via market orders
# turnover matters
def estimate_imb_pnl(asset, thr=0.2, hold=10):
    mid=clean(H0[asset]['mid'])
    imb=clean(H0[asset]['imbalance'])
    spr=clean(H0[asset]['spread'])
    # generate signal target [-1,0,1]
    target=np.zeros(len(mid))
    for i in range(len(mid)):
        if not np.isfinite(imb[i]):
            target[i]=target[i-1] if i>0 else 0
        elif imb[i] > thr:
            target[i]=1
        elif imb[i] < -thr:
            target[i]=-1
        else:
            target[i]=0
    # hold logic? simple
    # simulate trading with max 2 lots per step, spread cost = abs(delta_position)* spr/2
    # position in lots: target *15
    # pnl = pos * price change - cost
    pos_lots = target*15 # target pos
    # enforce 2 lots per step speed limit: smooth
    pos_eff=np.zeros(len(mid))
    cur=0
    for i in range(len(mid)):
        desired=pos_lots[i]
        delta=np.clip(desired-cur, -2, 2)
        cur+=delta
        pos_eff[i]=cur
    pnl=0.0
    cost=0.0
    for i in range(1,len(mid)):
        if not (np.isfinite(mid[i]) and np.isfinite(mid[i-1])):
            continue
        pnl+= pos_eff[i-1]*(mid[i]-mid[i-1])
        # cost of trade at i-1 to i?
        delta=pos_eff[i]-pos_eff[i-1]
        if delta!=0 and np.isfinite(spr[i]):
            cost+= abs(delta)*(spr[i]/2)
            # fees: for BONDs fee 0? not listed, assume 0
    return float(pnl-cost), float(pnl), float(cost), float(np.nansum(np.abs(np.diff(pos_eff)))/len(mid))

