def sim_pnl(mid, spr, target_raw, hold_steps=0):
    # target_raw in [-1,1] each step; we mimic call every 10 steps with hold
    # Actually simulate per step signal sampled every 10 steps and hold
    # Simplify: signal held constant between calls
    n=len(mid)
    target=np.zeros(n)
    # Build target sampled every 10 steps
    last=0
    hold=0
    pos_target=0
    for i in range(n):
        if i%10==0:
            if hold>0:
                hold-=1
            else:
                # update target based on raw at i
                if np.isfinite(target_raw[i]):
                    pos_target=target_raw[i]
                    if pos_target!=target[i-1] if i>0 else 1:
                        # if changed, set hold
                        hold=hold_steps//10
                else:
                    pos_target=target[i-1] if i>0 else 0
            last=pos_target
        target[i]=last
    # execution with 2 lots per step limit
    lots_target=target*15
    pos=np.zeros(n)
    cur=0
    for i in range(n):
        desired=lots_target[i]
        delta=np.clip(desired-cur, -2,2)
        cur+=delta
        pos[i]=cur
    pnl=0.0
    cost=0.0
    for i in range(1,n):
        if np.isfinite(mid[i]) and np.isfinite(mid[i-1]):
            pnl+= pos[i-1]*(mid[i]-mid[i-1])
        delta=pos[i]-pos[i-1]
        if delta!=0 and np.isfinite(spr[i]):
            cost+= abs(delta)*(spr[i]/2)
    return pnl-cost, pnl, cost

